-- v2 hierarchy seed for "financial-education". GENERATED by `npm run v2:hierarchy` in coursegen; do not edit by hand.
--
-- Creates 28 adventure(s), 28 saga(s), 112 topic(s), 112 lesson(s) and 313 topic-to-KC link(s).
-- Create-only and idempotent: every INSERT is ON CONFLICT DO NOTHING, so a rerun changes nothing and an existing row is never overwritten.
-- Ids are UUIDv5 of the slug path (ids.json maps each lesson slug to its public.lessons.id).
-- Nothing is published: adventures, sagas and topics are inserted as draft and lessons as review. A human publishes.
-- The course row is only created when the slug is absent. Adventures resolve the course by slug and append after its existing adventures.
-- Knowledge components resolve by key from public.kc (seed:kc must have loaded them, draft ones included).
--
-- REVIEW GATE: the file ends in ROLLBACK, so running it as-is persists nothing. It still executes every statement and the
-- completeness check, which raises if any row or link did not land. After reading it, replace the final ROLLBACK with COMMIT.

BEGIN;

DO $lfkc$
DECLARE v_missing text;
BEGIN
  SELECT string_agg(k.key, ', ') INTO v_missing FROM unnest(ARRAY['biz.goods-vs-services', 'biz.needs-vs-wants', 'biz.saving-goal', 'biz.trade-and-markets', 'biz.value-of-work', 'biz.what-is-price', 'life.advertising-literacy', 'life.banks-and-accounts', 'life.barter', 'life.common-good', 'life.community-projects', 'life.data-privacy', 'life.effort-and-work', 'life.giving', 'life.goal-planning', 'life.jobs-help-others', 'life.opportunity-cost', 'life.patience-and-waiting', 'life.recurring-costs', 'life.reflect-on-learning', 'life.review-and-adjust-plan', 'life.safe-keeping', 'life.save-spend-share', 'life.saving-for-later', 'life.scam-awareness', 'life.shared-resources', 'life.smart-shopping', 'life.think-before-buying', 'life.track-earnings', 'life.wants-and-choices', 'life.what-money-is', 'money.add-money', 'money.coin-recognition', 'money.compare-amounts', 'money.count-like-coins', 'money.count-mixed-coins', 'money.equal-sharing', 'money.estimate-total', 'money.fraction-of-amount', 'money.make-amount', 'money.make-change-counting-up', 'money.percent-intro', 'money.savings-plan-math', 'money.simple-budget', 'money.simple-interest-peek', 'money.subtract-money', 'money.unit-price']) AS k(key)
  WHERE NOT EXISTS (SELECT 1 FROM public.kc WHERE kc.key = k.key);
  IF v_missing IS NOT NULL THEN RAISE EXCEPTION 'knowledge components missing from public.kc (run backend seed:kc first): %', v_missing; END IF;
END
$lfkc$;

