INSERT INTO public.topics (id, saga_id, position, slug, title, learning_objective, kind, status)
VALUES
  ('ac41587d-de4c-543f-8ddf-03fa1f74fd6b', '59852db9-98fa-5757-b5e4-5327ed9cc866', 1, 'fe-69-05-name-the-coins', $lf${"en-US":"Name the coins, count the pile","es-MX":"Nombra las monedas y cuenta la pila","pt-BR":"Nomeie as moedas e conte a pilha"}$lf$::jsonb, $lf${"en-US":"Name each coin and bill and say how much it is worth.","es-MX":"Nombrar cada moneda y billete y decir cuánto vale.","pt-BR":"Nomear cada moeda e cédula e dizer quanto vale."}$lf$::jsonb, 'teaching', 'draft'),
  ('a341fd0b-02fc-5e15-8fd4-2990402c2627', '59852db9-98fa-5757-b5e4-5327ed9cc866', 2, 'fe-69-06-things-and-help', $lf${"en-US":"Things and help, needs and wants","es-MX":"Cosas y ayuda, necesidades y deseos","pt-BR":"Coisas e ajuda, necessidades e desejos"}$lf$::jsonb, $lf${"en-US":"Tell apart selling a thing from selling help or work.","es-MX":"Distinguir entre vender una cosa y vender ayuda o trabajo.","pt-BR":"Distinguir entre vender uma coisa e vender ajuda ou trabalho."}$lf$::jsonb, 'teaching', 'draft'),
  ('c54534c2-db8e-5a46-a70c-332845dae0c9', '59852db9-98fa-5757-b5e4-5327ed9cc866', 3, 'fe-69-07-people-who-work', $lf${"en-US":"People who work","es-MX":"Personas que trabajan","pt-BR":"Pessoas que trabalham"}$lf$::jsonb, $lf${"en-US":"Recognize that getting things done takes effort, that helping at home is work, and that finishing a task matters.","es-MX":"Reconocer que lograr algo pide esfuerzo, que ayudar en casa es trabajo y que terminar una tarea importa.","pt-BR":"Reconhecer que conseguir algo exige esforço, que ajudar em casa é trabalho e que terminar uma tarefa importa."}$lf$::jsonb, 'teaching', 'draft'),
  ('962778ec-d590-5e1c-94cf-9686c93b827d', '59852db9-98fa-5757-b5e4-5327ed9cc866', 4, 'fe-69-08-price-and-coins-left', $lf${"en-US":"Price and coins left","es-MX":"El precio y las monedas que quedan","pt-BR":"O preço e as moedas que sobram"}$lf$::jsonb, $lf${"en-US":"Explain that a price is what a buyer gives to get something.","es-MX":"Explicar que un precio es lo que el comprador da para recibir algo.","pt-BR":"Explicar que um preço é o que o comprador dá para receber algo."}$lf$::jsonb, 'teaching', 'draft'),
  ('cb4d9b46-8a3c-5fb9-b8de-ae4a2c12a1ae', '6ddbc9b8-92fd-5d7a-aaf5-336b6dd14f77', 1, 'fe-69-01-count-coins', $lf${"en-US":"Count coins, fill a light pouch","es-MX":"Cuenta monedas, llena la bolsita","pt-BR":"Conte moedas, encha a bolsinha"}$lf$::jsonb, $lf${"en-US":"Find the total of mixed coins and bills, starting from the biggest value.","es-MX":"Encontrar el total de monedas y billetes mezclados, empezando por el de mayor valor.","pt-BR":"Encontrar o total de moedas e cédulas misturadas, começando pelo maior valor."}$lf$::jsonb, 'teaching', 'draft'),
  ('231c129c-5f78-5f1d-91ed-d56863443f0a', '6ddbc9b8-92fd-5d7a-aaf5-336b6dd14f77', 2, 'fe-69-02-change-counting-up', $lf${"en-US":"Give change by counting up","es-MX":"Da el cambio contando hacia arriba","pt-BR":"Dê o troco contando para cima"}$lf$::jsonb, $lf${"en-US":"Give the right change by counting up from the price to the money handed over.","es-MX":"Dar el cambio correcto contando desde el precio hasta el dinero entregado.","pt-BR":"Dar o troco certo contando do preço até o dinheiro entregue."}$lf$::jsonb, 'teaching', 'draft'),
  ('e07403db-0c28-5628-83f9-4aa3d0c31d59', '6ddbc9b8-92fd-5d7a-aaf5-336b6dd14f77', 3, 'fe-69-03-needs-and-wants', $lf${"en-US":"Needs and wants","es-MX":"Necesidades y deseos","pt-BR":"Necessidades e desejos"}$lf$::jsonb, $lf${"en-US":"Name things you want and explain why you cannot have everything at once, so you choose.","es-MX":"Nombrar cosas que quieres y explicar por qué no puedes tenerlo todo a la vez, así que eliges.","pt-BR":"Nomear coisas que você quer e explicar por que não dá para ter tudo de uma vez, então você escolhe."}$lf$::jsonb, 'teaching', 'draft'),
  ('7983c595-795c-5874-ade1-0ceea01e1aa9', '6ddbc9b8-92fd-5d7a-aaf5-336b6dd14f77', 4, 'fe-69-04-market-stall', $lf${"en-US":"The yard sale snack table","es-MX":"Un puesto en el tianguis","pt-BR":"Uma barraca na feira livre"}$lf$::jsonb, $lf${"en-US":"Add two prices or amounts of money together.","es-MX":"Sumar dos precios o cantidades de dinero.","pt-BR":"Somar dois preços ou quantias de dinheiro."}$lf$::jsonb, 'teaching', 'draft'),
  ('30ca48f6-8bda-5c0c-8e6c-0e916987a6ef', 'e5e496ea-9ecf-5a87-9260-663189634d16', 1, 'fe-69-09-swap-day', $lf${"en-US":"Swap day","es-MX":"Día de intercambio","pt-BR":"Dia de troca"}$lf$::jsonb, $lf${"en-US":"Swap something you have for something you want, and spot when a swap gets stuck because the other person wants something else.","es-MX":"Cambiar algo que tienes por algo que quieres y notar cuándo el trueque se traba porque la otra persona quiere otra cosa.","pt-BR":"Trocar algo que você tem por algo que quer e perceber quando a troca trava porque a outra pessoa quer outra coisa."}$lf$::jsonb, 'teaching', 'draft'),
  ('918f2c95-51ba-573b-8b26-c295f7c6a8c1', 'e5e496ea-9ecf-5a87-9260-663189634d16', 2, 'fe-69-10-why-coins', $lf${"en-US":"Why coins work","es-MX":"Por qué sirven las monedas","pt-BR":"Por que as moedas funcionam"}$lf$::jsonb, $lf${"en-US":"Explain that money is something everyone agrees to accept in exchange, and that it works because people trust it.","es-MX":"Explicar que el dinero es algo que todos aceptan a cambio y que funciona porque la gente confía en él.","pt-BR":"Explicar que o dinheiro é algo que todos aceitam em troca e que funciona porque as pessoas confiam nele."}$lf$::jsonb, 'teaching', 'draft'),
  ('54451bff-f199-52ce-836e-3dfd9ba96c44', 'e5e496ea-9ecf-5a87-9260-663189634d16', 3, 'fe-69-11-which-stall-is-cheaper', $lf${"en-US":"Which stall is cheaper","es-MX":"¿Qué puesto es más barato?","pt-BR":"Qual barraca é mais barata?"}$lf$::jsonb, $lf${"en-US":"Check and compare prices and quality in different places before choosing what to buy.","es-MX":"Revisar y comparar precios y calidad en distintos lugares antes de elegir qué comprar.","pt-BR":"Verificar e comparar preços e qualidade em lugares diferentes antes de escolher o que comprar."}$lf$::jsonb, 'teaching', 'draft'),
  ('7ec94588-61ff-56dc-815d-be5713bb6f92', 'e5e496ea-9ecf-5a87-9260-663189634d16', 4, 'fe-69-12-pause-before-you-buy', $lf${"en-US":"Pause before you buy","es-MX":"Haz una pausa antes de comprar","pt-BR":"Pare antes de comprar"}$lf$::jsonb, $lf${"en-US":"Pause before a purchase, ask whether it can wait, and ask a trusted adult when a choice is hard.","es-MX":"Detenerse antes de una compra, preguntarse si puede esperar y pedir ayuda a un adulto de confianza cuando la decisión es difícil.","pt-BR":"Parar antes de uma compra, perguntar se ela pode esperar e pedir ajuda a um adulto de confiança quando a escolha é difícil."}$lf$::jsonb, 'teaching', 'draft'),
  ('8374a055-02f4-560b-b8ac-62e57957a552', '09005fd1-1580-5fdd-af4e-a34b7daabbfb', 1, 'fe-69-13-earn-and-write-it-down', $lf${"en-US":"Earn it and write it down","es-MX":"Gana y anótalo","pt-BR":"Ganhe e anote"}$lf$::jsonb, $lf${"en-US":"Explain that time and effort put into work deserve to be paid.","es-MX":"Explicar que el tiempo y el esfuerzo del trabajo merecen un pago.","pt-BR":"Explicar que o tempo e o esforço do trabalho merecem pagamento."}$lf$::jsonb, 'teaching', 'draft'),
  ('8b5db202-c158-554a-b04a-082bde97690a', '09005fd1-1580-5fdd-af4e-a34b7daabbfb', 2, 'fe-69-14-goal-jar', $lf${"en-US":"A jar for my goal","es-MX":"Una alcancía para mi meta","pt-BR":"Um cofrinho para a minha meta"}$lf$::jsonb, $lf${"en-US":"Set a goal and decide how much to keep aside each time money comes in.","es-MX":"Fijar una meta y decidir cuánto apartar cada vez que entra dinero.","pt-BR":"Definir uma meta e decidir quanto guardar cada vez que entra dinheiro."}$lf$::jsonb, 'teaching', 'draft'),
  ('70ba4f34-3463-5456-9b9a-5745ff278302', '09005fd1-1580-5fdd-af4e-a34b7daabbfb', 3, 'fe-69-15-wait-and-keep-safe', $lf${"en-US":"Wait and keep safe","es-MX":"Espera y cuida tus monedas","pt-BR":"Espere e guarde com segurança"}$lf$::jsonb, $lf${"en-US":"Compare a small thing you could have now with a bigger thing you could have later, and choose to wait when it is worth it.","es-MX":"Comparar algo pequeño que podrías tener ahora con algo más grande que podrías tener después, y esperar cuando vale la pena.","pt-BR":"Comparar algo pequeno que você poderia ter agora com algo maior que poderia ter depois, e esperar quando vale a pena."}$lf$::jsonb, 'teaching', 'draft'),
  ('1503df9e-97b2-5c92-9732-c8b4cecd98a8', '09005fd1-1580-5fdd-af4e-a34b7daabbfb', 4, 'fe-69-16-three-jars', $lf${"en-US":"Three jars","es-MX":"Tres frascos","pt-BR":"Três potes"}$lf$::jsonb, $lf${"en-US":"Split the coins you receive between saving, spending and sharing, and explain the choice.","es-MX":"Repartir las monedas que recibes entre ahorrar, gastar y compartir, y explicar la decisión.","pt-BR":"Dividir as moedas que você recebe entre poupar, gastar e compartilhar, e explicar a escolha."}$lf$::jsonb, 'teaching', 'draft'),
  ('93df7815-dca3-53a7-b75c-b2e80ef3904a', 'd6d4ad2d-5509-53b9-b4fc-826e9984ddfd', 1, 'fe-69-17-where-money-waits', $lf${"en-US":"Where money waits","es-MX":"Dónde espera el dinero","pt-BR":"Onde o dinheiro espera"}$lf$::jsonb, $lf${"en-US":"Choose a safe place for savings, look after it, and keep saving even after a small loss.","es-MX":"Elegir un lugar seguro para los ahorros, cuidarlo y seguir ahorrando aunque se pierda algo pequeño.","pt-BR":"Escolher um lugar seguro para as economias, cuidar dele e continuar guardando mesmo depois de uma pequena perda."}$lf$::jsonb, 'teaching', 'draft'),
  ('a973807f-ae88-53c9-886e-c8638c943432', 'd6d4ad2d-5509-53b9-b4fc-826e9984ddfd', 2, 'fe-69-18-grown-up-account', $lf${"en-US":"A grown-up account","es-MX":"Una cuenta con un adulto","pt-BR":"Uma conta com um adulto"}$lf$::jsonb, $lf${"en-US":"Explain what a bank and a savings account are for, how money is taken out, and how cards connect to saved money.","es-MX":"Explicar para qué sirven un banco y una cuenta de ahorro, cómo se retira el dinero y cómo las tarjetas se conectan con el dinero guardado.","pt-BR":"Explicar para que servem um banco e uma conta poupança, como o dinheiro é retirado e como os cartões se ligam ao dinheiro guardado."}$lf$::jsonb, 'teaching', 'draft'),
  ('a3705913-13f7-597c-a21c-5f9b43f61b84', 'd6d4ad2d-5509-53b9-b4fc-826e9984ddfd', 3, 'fe-69-19-secrets-stay-secret', $lf${"en-US":"Secrets stay secret","es-MX":"Los secretos se cuidan","pt-BR":"Segredos ficam protegidos"}$lf$::jsonb, $lf${"en-US":"Keep private information, passwords and photos protected, and share them only with permission from a trusted adult.","es-MX":"Proteger la información privada, las contraseñas y las fotos, y compartirlas solo con permiso de un adulto de confianza.","pt-BR":"Proteger informações pessoais, senhas e fotos, e compartilhá-las só com permissão de um adulto de confiança."}$lf$::jsonb, 'teaching', 'draft'),
  ('5543efb1-eb36-5718-80a2-ccd1031344e7', 'd6d4ad2d-5509-53b9-b4fc-826e9984ddfd', 4, 'fe-69-20-stop-check-ask', $lf${"en-US":"Stop, check, ask","es-MX":"Para, revisa y pregunta","pt-BR":"Pare, confira e pergunte"}$lf$::jsonb, $lf${"en-US":"Spot the signs of a suspicious message or fake profile, stop, and tell a trusted adult.","es-MX":"Notar las señales de un mensaje sospechoso o de un perfil falso, detenerse y contarlo a un adulto de confianza.","pt-BR":"Notar os sinais de uma mensagem suspeita ou de um perfil falso, parar e contar a um adulto de confiança."}$lf$::jsonb, 'teaching', 'draft'),
  ('6d53c03a-c175-5676-9817-189347f4fe91', 'b0d30666-04c4-523d-aa02-e33800813ea9', 1, 'fe-69-21-count-a-small-plan', $lf${"en-US":"Count a small plan","es-MX":"Cuenta un plan pequeño","pt-BR":"Conte um plano pequeno"}$lf$::jsonb, $lf${"en-US":"Choose what to buy so the total never passes the money available.","es-MX":"Elegir qué comprar de modo que el total nunca pase del dinero disponible.","pt-BR":"Escolher o que comprar para que o total nunca passe do dinheiro disponível."}$lf$::jsonb, 'teaching', 'draft'),
  ('9001cf1b-599f-5921-ae29-642b039c5887', 'b0d30666-04c4-523d-aa02-e33800813ea9', 2, 'fe-69-22-steps-to-my-goal', $lf${"en-US":"Steps to my goal","es-MX":"Pasos hacia mi meta","pt-BR":"Passos até minha meta"}$lf$::jsonb, $lf${"en-US":"Work out how many weeks of saving it takes to reach a goal.","es-MX":"Calcular cuántas semanas de ahorro se necesitan para llegar a una meta.","pt-BR":"Calcular quantas semanas de poupança são necessárias para alcançar uma meta."}$lf$::jsonb, 'teaching', 'draft'),
  ('78ab4bf3-85dd-5519-aa0e-bea6f7536928', 'b0d30666-04c4-523d-aa02-e33800813ea9', 3, 'fe-69-23-date-for-my-goal', $lf${"en-US":"A date for my goal","es-MX":"Fecha para mi meta","pt-BR":"Data para minha meta"}$lf$::jsonb, $lf${"en-US":"Turn a wish into a goal with a size and a date, break it into steps, and think ahead about obstacles.","es-MX":"Convertir un deseo en una meta con tamaño y fecha, dividirla en pasos y pensar por adelantado en los obstáculos.","pt-BR":"Transformar um desejo em uma meta com tamanho e data, dividi-la em passos e pensar antes nos obstáculos."}$lf$::jsonb, 'teaching', 'draft'),
